parameters.jsCode:
// n8n Code node: "Enforce Contract" (Run Once for All Items).
// Whatever the agent produced, downstream nodes only ever see a clean
// { status, message, chatReply } object, plus blueprint + contact when the
// blueprint is ready to deliver.
const FALLBACK_MESSAGE = 'Sorry, I lost my train of thought for a second. Could you tell me once more which repetitive task you would most like to hand off?';
const ASK_CONTACT = 'Your blueprint is ready! What is your first name, and which email address should I send it to?';
const LIMIT_REACHED = "I've already sent the blueprint to that address. Check your inbox (and spam folder), or tell me what you'd like to change in the design.";
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

// Abuse guard for the public chat: at most 2 emails per chat session and 3
// per recipient per 24 hours. Only a hash of each address is stored.
// Workflow static data persists in production (active) executions only.
const SEND_LIMITS = { perSession: 2, perRecipientPerDay: 3, windowMs: 24 * 60 * 60 * 1000 };

function hash(text) {
  let h = 0x811c9dc5;
  for (let i = 0; i < text.length; i += 1) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16);
}

function reserveSend(email) {
  const data = $getWorkflowStaticData('global');
  const now = Date.now();
  const sessionId = String($('When chat message received').first().json.sessionId || 'unknown');
  const sends = (Array.isArray(data.blueprintSends) ? data.blueprintSends : [])
    .filter(function (s) { return now - s.at < SEND_LIMITS.windowMs; });
  const recipient = hash(email);
  const bySession = sends.filter(function (s) { return s.session === sessionId; }).length;
  const byRecipient = sends.filter(function (s) { return s.recipient === recipient; }).length;
  if (bySession >= SEND_LIMITS.perSession || byRecipient >= SEND_LIMITS.perRecipientPerDay) {
    data.blueprintSends = sends;
    return false;
  }
  sends.push({ at: now, session: sessionId, recipient: recipient });
  data.blueprintSends = sends.slice(-500);
  return true;
}

function str(value, max) {
  if (value === null || value === undefined) return '';
  return String(value).replace(/\s+/g, ' ').trim().slice(0, max);
}

function strList(value, max) {
  if (!Array.isArray(value)) return [];
  return value.map(function (v) { return str(v, max); }).filter(function (v) { return v.length > 0; });
}

function unwrap(raw) {
  let value = raw;
  for (let i = 0; i < 3; i += 1) {
    if (typeof value === 'string') {
      const text = value.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
      try { value = JSON.parse(text); } catch { return null; }
      continue;
    }
    if (value && typeof value === 'object' && !value.status && value.output !== undefined) {
      value = value.output;
      continue;
    }
    break;
  }
  return value && typeof value === 'object' ? value : null;
}

function cleanBlueprint(b) {
  if (!b || typeof b !== 'object') return null;
  const kinds = ['deterministic', 'ai', 'human'];
  const steps = (Array.isArray(b.steps) ? b.steps : []).slice(0, 8).map(function (s) {
    const kind = s && kinds.indexOf(s.kind) !== -1 ? s.kind : 'deterministic';
    return { title: str(s && s.title, 80), description: str(s && s.description, 400), kind: kind };
  }).filter(function (s) { return s.title && s.description; });
  const integrations = (Array.isArray(b.integrations) ? b.integrations : []).map(function (i) {
    return { name: str(i && i.name, 60), role: str(i && i.role, 200) };
  }).filter(function (i) { return i.name && i.role; });
  let hours = b.estimatedHoursSavedPerWeek;
  if (typeof hours === 'string' && hours.trim() !== '') hours = Number(hours);
  hours = typeof hours === 'number' && isFinite(hours) ? Math.min(80, Math.max(0, hours)) : null;
  const out = {
    name: str(b.name, 120),
    problem: str(b.problem, 600),
    trigger: str(b.trigger, 200),
    inputs: strList(b.inputs, 200),
    steps: steps,
    integrations: integrations,
    exceptions: strList(b.exceptions, 300),
    outputs: strList(b.outputs, 200),
    complexity: ['beginner', 'intermediate', 'advanced'].indexOf(b.complexity) !== -1 ? b.complexity : 'intermediate',
    difficulty: ['easy', 'moderate', 'hard'].indexOf(b.difficulty) !== -1 ? b.difficulty : 'moderate',
    estimatedHoursSavedPerWeek: hours,
    assumptions: strList(b.assumptions, 300)
  };
  if (!out.name || !out.problem || !out.trigger) return null;
  if (out.inputs.length < 1 || out.steps.length < 2 || out.integrations.length < 1 || out.outputs.length < 1) return null;
  return out;
}

function cleanContact(c) {
  if (!c || typeof c !== 'object') return null;
  const firstName = str(c.firstName, 80);
  const email = str(c.email, 200).toLowerCase();
  if (!firstName || !EMAIL.test(email)) return null;
  return { firstName: firstName, email: email };
}

function question(message, quickReplies) {
  const replies = (Array.isArray(quickReplies) ? quickReplies : []).map(function (q) {
    return str(q && (q.label || q.value), 60);
  }).filter(Boolean).slice(0, 6);
  const chatReply = replies.length ? message + '\n\nYou could answer: ' + replies.join(' · ') : message;
  return { status: 'question', message: message, chatReply: chatReply };
}

const item = $input.first().json;
const candidate = item.error ? null : unwrap(item.output !== undefined ? item.output : item);
let response = question(FALLBACK_MESSAGE);

if (candidate && candidate.status === 'blueprint') {
  const blueprint = cleanBlueprint(candidate.blueprint);
  const contact = cleanContact(candidate.contact);
  if (blueprint && contact && !reserveSend(contact.email)) {
    response = question(LIMIT_REACHED);
  } else if (blueprint && contact) {
    const message = str(candidate.message, 300) || 'Here is your automation blueprint.';
    response = { status: 'blueprint', message: message, chatReply: message, blueprint: blueprint, contact: contact };
  } else if (blueprint) {
    response = question(ASK_CONTACT);
  }
} else if (candidate && candidate.status === 'question') {
  const message = str(candidate.message, 2000);
  if (message) response = question(message, candidate.quickReplies);
}

return [{ json: response }];

// n8n Code node: "Build n8n Starter Workflow" (Run Once for All Items).
// Turns the blueprint into a portable,
// inactive, credential-free n8n workflow the visitor can import.
const STARTER_SUFFIX = '— n8n Starter';
const GENERATED_BY = 'the **Automation Discovery Agent**';
const TRIGGER_WORDS = /\b(trigger|watch|listen|schedule)\b/i;

function cleanInline(value, maxLength) {
  const max = maxLength === undefined ? 160 : maxLength;
  return String(value).replace(/[\r\n]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
}

function slug(value, fallback) {
  const result = String(value)
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 72);
  return result || fallback;
}

function nodeId(index) {
  return '+1234567890-' + String(index).padStart(12, '0');
}

function parseTime(trigger) {
  const twelveHour = trigger.match(/\b(1[0-2]|0?[1-9])(?::([0-5]\d))?\s*(a\.?m\.?|p\.?m\.?)\b/i);
  if (twelveHour) {
    let hour = Number(twelveHour[1]) % 12;
    if (twelveHour[3].toLowerCase().startsWith('p')) hour += 12;
    return { hour: hour, minute: Number(twelveHour[2] ?? 0) };
  }
  const twentyFourHour = trigger.match(/\b(?:at\s+)?([01]?\d|2[0-3]):([0-5]\d)\b/i);
  return twentyFourHour
    ? { hour: Number(twentyFourHour[1]), minute: Number(twentyFourHour[2]) }
    : { hour: 9, minute: 0 };
}

function scheduleInterval(trigger) {
  const time = parseTime(trigger);
  const lower = trigger.toLowerCase();
  const weekdays = [
    [/\bsunday\b/, 0], [/\bmonday\b/, 1], [/\btuesday\b/, 2], [/\bwednesday\b/, 3],
    [/\bthursday\b/, 4], [/\bfriday\b/, 5], [/\bsaturday\b/, 6],
  ];
  const namedDays = weekdays.filter(function (w) { return w[0].test(lower); }).map(function (w) { return w[1]; });
  if (/\bweekdays?\b/.test(lower)) {
    return { field: 'weeks', triggerAtDay: [1, 2, 3, 4, 5], triggerAtHour: time.hour, triggerAtMinute: time.minute };
  }
  if (namedDays.length > 0 || /\bweekly\b/.test(lower)) {
    return { field: 'weeks', triggerAtDay: namedDays.length > 0 ? namedDays : [1], triggerAtHour: time.hour, triggerAtMinute: time.minute };
  }
  return { field: 'days', triggerAtHour: time.hour, triggerAtMinute: time.minute };
}

function triggerNode(blueprint) {
  const firstStep = blueprint.steps[0];
  const context = blueprint.trigger + ' ' + (firstStep ? firstStep.title : '') + ' ' + (firstStep ? firstStep.description : '');
  const common = {
    id: nodeId(1),
    position: [-420, 80],
    notes: 'Blueprint trigger: ' + cleanInline(blueprint.trigger, 300),
  };

  if (/\b(gmail|inbox|email)\b/i.test(context) && /\b(arriv|receiv|watch|inbox)\w*\b/i.test(context)) {
    return Object.assign({}, common, {
      name: 'Gmail Trigger',
      type: 'n8n-nodes-base.gmailTrigger',
      typeVersion: 1.3,
      parameters: { pollTimes: { item: [{ mode: 'everyMinute' }] }, simple: false, filters: {} },
      notes: common.notes + '\n\nSETUP: Select your Gmail credential and narrow the filters before activation.',
    });
  }
  if (/\b(webhook|form submission|website form)\b/i.test(context)) {
    return Object.assign({}, common, {
      name: 'Webhook Trigger',
      type: 'n8n-nodes-base.webhook',
      typeVersion: 2.1,
      parameters: { httpMethod: 'POST', path: 'starter-' + slug(blueprint.name, 'automation'), responseMode: 'onReceived', options: {} },
      notes: common.notes + '\n\nSETUP: Publish the workflow, then connect the calling form or app to the production webhook URL.',
    });
  }
  if (/\b(schedule|daily|weekly|weekday|every (?:day|morning|week))\b/i.test(context)) {
    return Object.assign({}, common, {
      name: 'Schedule Trigger',
      type: 'n8n-nodes-base.scheduleTrigger',
      typeVersion: 1.3,
      parameters: { rule: { interval: [scheduleInterval(blueprint.trigger)] } },
      notes: common.notes + '\n\nSETUP: Verify the workflow timezone and schedule before activation.',
    });
  }
  return Object.assign({}, common, {
    name: 'Manual Trigger',
    type: 'n8n-nodes-base.manualTrigger',
    typeVersion: 1,
    parameters: {},
    notes: common.notes + '\n\nSETUP: Replace this starter trigger with the event that begins the real process.',
  });
}

function entityIdFromInputs(inputs) {
  const deviceInput = inputs.find(function (input) { return /\b(device id|smart plug|socket)\b/i.test(input); });
  if (!deviceInput) return 'switch.replace_with_entity_id';
  const match = deviceInput.match(/\(([^)]+)\)/);
  const parenthetical = match ? match[1] : undefined;
  const candidate = cleanInline(parenthetical ?? deviceInput.replace(/^.*?:\s*/, ''), 100);
  return 'switch.' + slug(candidate, 'replace-with-entity-id').replace(/-/g, '_');
}

function isHomeAssistantAction(blueprint, step) {
  const integrations = blueprint.integrations.map(function (i) { return i.name; }).join(' ');
  const context = step.title + ' ' + step.description + ' ' + integrations;
  return /\b(home assistant|smartthings|zigbee2mqtt)\b/i.test(context) &&
    /\b(smart plug|socket|switch|power|turn (?:on|off))\b/i.test(context);
}

function actionNode(blueprint, step, index, position) {
  const base = {
    id: nodeId(index + 1),
    name: index + '. ' + cleanInline(step.title, 90),
    position: position,
    notes: step.kind.toUpperCase() + ' STEP\n\n' + cleanInline(step.description, 400),
  };
  if (isHomeAssistantAction(blueprint, step)) {
    const turnOff = /\b(turn|power|switch)\s+off\b/i.test(step.title + ' ' + step.description);
    return Object.assign({}, base, {
      type: 'n8n-nodes-base.homeAssistant',
      typeVersion: 1,
      parameters: {
        resource: 'service',
        operation: 'call',
        domain: 'switch',
        service: turnOff ? 'turn_off' : 'turn_on',
        serviceAttributes: { attributes: [{ name: 'entity_id', value: entityIdFromInputs(blueprint.inputs) }] },
      },
      notes: base.notes + "\n\nSETUP: Add a Home Assistant API credential and verify the entity_id. For SmartThings or Zigbee2MQTT, replace this node with that platform's equivalent action.",
    });
  }
  return Object.assign({}, base, {
    type: 'n8n-nodes-base.noOp',
    typeVersion: 1,
    parameters: {},
    notes: base.notes + "\n\nSETUP: Replace this planning node with the named n8n integration, configure its fields, and add its credential if required.",
  });
}

function setupNote(blueprint) {
  const integrations = blueprint.integrations
    .map(function (i) { return '- **' + cleanInline(i.name, 80) + ':** ' + cleanInline(i.role, 220); })
    .join('\n');
  const assumptions = blueprint.assumptions.map(function (a) { return '- ' + cleanInline(a, 260); }).join('\n');
  const exceptions = blueprint.exceptions.map(function (e) { return '- ' + cleanInline(e, 260); }).join('\n');
  return {
    id: nodeId(0),
    name: 'START HERE',
    type: 'n8n-nodes-base.stickyNote',
    typeVersion: 1,
    position: [-660, -420],
    parameters: {
      width: 720,
      height: 340,
      color: 5,
      content: '# ' + cleanInline(blueprint.name, 120) + '\n\nCredential-free starter generated by ' + GENERATED_BY + '.\n\n## Before activation\n1. Open each node marked **SETUP** in its Notes tab.\n2. Add your own credentials; none are included in this file.\n3. Replace any planning nodes and verify IDs, destinations, filters, timezone, and exception paths.\n4. Run with test data before publishing.\n\n## Recommended integrations\n' + integrations + '\n\n## Assumptions\n' + (assumptions || '- None recorded') + '\n\n## Exceptions\n' + (exceptions || '- None recorded'),
    },
  };
}

function isRepresentedByTrigger(step, index) {
  return index === 0 && TRIGGER_WORDS.test(step.title + ' ' + step.description);
}

function blueprintToN8nWorkflow(blueprint) {
  const trigger = triggerNode(blueprint);
  const actionSteps = blueprint.steps.filter(function (step, index) { return !isRepresentedByTrigger(step, index); });
  const actionNodes = actionSteps.map(function (step, index) {
    return actionNode(blueprint, step, index + 1, [-140 + index * 260, 80]);
  });
  const connectedNodes = [trigger].concat(actionNodes);
  const connections = {};
  for (let index = 0; index < connectedNodes.length - 1; index += 1) {
    connections[connectedNodes[index].name] = {
      main: [[{ node: connectedNodes[index + 1].name, type: 'main', index: 0 }]],
    };
  }
  return {
    name: cleanInline(blueprint.name, 100) + ' ' + STARTER_SUFFIX,
    active: false,
    nodes: [setupNote(blueprint)].concat(connectedNodes),
    connections: connections,
    settings: { executionOrder: 'v1' },
    pinData: {},
    meta: { templateCredsSetupCompleted: false },
    tags: [],
  };
}

const item = $input.first().json;
const workflow = blueprintToN8nWorkflow(item.blueprint);
const workflowJson = JSON.stringify(workflow, null, 2);

return [{
  json: Object.assign({}, item, {
    workflowFilename: slug(item.blueprint.name, 'automation') + '-n8n-workflow.json',
    workflowJson: workflowJson,
    workflowBase64: Buffer.from(workflowJson, 'utf8').toString('base64'),
  }),
}];

// n8n Code node: "Build Blueprint Email" (Run Once for All Items).
// Renders the blueprint as an email-safe,
// inline-styled HTML document. Every dynamic value is escaped because agent
// and visitor text is untrusted.
const KIND_META = {
  deterministic: { label: "Workflow step", color: "#9aa1b0" },
  ai: { label: "AI reasoning", color: "#ea4b71" },
  human: { label: "Human approval", color: "#d9a23b" },
};

const COMPLEXITY_LABEL = {
  beginner: "Beginner",
  intermediate: "Intermediate",
  advanced: "Advanced",
};

const DIFFICULTY_LABEL = {
  easy: "Easy build",
  moderate: "Moderate build",
  hard: "Ambitious build",
};

function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function sectionLabel(label) {
  return `<p style="margin:0 0 10px;color:#9aa1b0;font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;font-size:11px;line-height:16px;letter-spacing:1.5px;text-transform:uppercase;">${escapeHtml(label)}</p>`;
}

function bulletList(items, emptyLabel) {
  const values = items.length > 0 ? items : [emptyLabel];
  return values
    .map(
      (item) =>
        `<tr><td style="width:16px;padding:0 0 8px;color:#9aa1b0;vertical-align:top;">&mdash;</td><td style="padding:0 0 8px;color:#b9bec9;font-size:14px;line-height:21px;">${escapeHtml(item)}</td></tr>`
    )
    .join("");
}

function blueprintToEmailHtml(blueprint, options) {
  const isBuildRequest = options.action === "build-request";
  const heading = isBuildRequest
    ? `Build request from ${options.firstName}`
    : blueprint.name;
  const intro = isBuildRequest
    ? `${options.firstName} (${options.email}) requested help building this automation.`
    : `Hi ${options.firstName}, here is the automation blueprint you requested.`;
  const estimatedImpact =
    blueprint.estimatedHoursSavedPerWeek !== null
      ? `${blueprint.estimatedHoursSavedPerWeek} hrs/week`
      : "Time saved depends on volume";
  const estimatedImpactNote =
    blueprint.estimatedHoursSavedPerWeek !== null
      ? "potentially saved — estimate, not a measurement"
      : "a quick conversation will size it";
  const capturedLabel = new Date(options.capturedAt).toLocaleString("en-US", {
    timeZone: "UTC",
    dateStyle: "medium",
    timeStyle: "short",
  });

  const workflowRows = [
    `<tr><td style="width:26px;padding:2px 13px 20px 0;vertical-align:top;"><span style="display:inline-block;width:10px;height:10px;border:2px solid #ea4b71;border-radius:50%;background:#0c0f16;"></span></td><td style="padding:0 0 20px;vertical-align:top;">${sectionLabel("trigger")}<p style="margin:-6px 0 0;color:#e9eaee;font-size:15px;font-weight:700;line-height:22px;">${escapeHtml(blueprint.trigger)}</p></td></tr>`,
    ...blueprint.steps.map((step) => {
      const meta = KIND_META[step.kind];
      return `<tr><td style="width:26px;padding:19px 13px 16px 0;vertical-align:top;"><span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:${meta.color};"></span></td><td style="padding:0 0 16px;vertical-align:top;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #2b3040;border-radius:12px;background:#121724;"><tr><td style="padding:16px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="color:#e9eaee;font-size:15px;font-weight:700;line-height:21px;">${escapeHtml(step.title)}</td><td align="right" style="color:${meta.color};font-size:11px;line-height:16px;white-space:nowrap;">${escapeHtml(meta.label)}</td></tr></table><p style="margin:7px 0 0;color:#9aa1b0;font-size:14px;line-height:21px;">${escapeHtml(step.description)}</p></td></tr></table></td></tr>`;
    }),
    ...(blueprint.exceptions.length > 0
      ? [
          `<tr><td style="width:26px;padding:17px 13px 16px 0;vertical-align:top;"><span style="display:inline-block;width:9px;height:9px;background:#d9a23b;transform:rotate(45deg);"></span></td><td style="padding:0 0 16px;vertical-align:top;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px dashed #795f2f;border-radius:12px;"><tr><td style="padding:16px;">${sectionLabel("exception path")}<table role="presentation" width="100%" cellpadding="0" cellspacing="0">${bulletList(blueprint.exceptions, "None identified yet")}</table></td></tr></table></td></tr>`,
        ]
      : []),
    `<tr><td style="width:26px;padding:3px 13px 0 0;vertical-align:top;"><span style="display:inline-block;width:10px;height:10px;border:2px solid #4cc27e;border-radius:50%;background:#0c0f16;"></span></td><td style="padding:0;vertical-align:top;">${sectionLabel("output")}<p style="margin:-6px 0 0;color:#e9eaee;font-size:14px;line-height:21px;">${blueprint.outputs.map(escapeHtml).join(" &middot; ")}</p></td></tr>`,
  ].join("");

  const inputs = blueprint.inputs
    .map(
      (input) =>
        `<span style="display:inline-block;margin:0 7px 8px 0;padding:6px 11px;border:1px solid #343a4a;border-radius:999px;color:#e9eaee;font-size:13px;line-height:18px;">${escapeHtml(input)}</span>`
    )
    .join("");

  const integrations = blueprint.integrations
    .map(
      (integration) =>
        `<tr><td style="width:34%;padding:0 14px 12px 0;color:#e9eaee;font-size:14px;font-weight:700;line-height:20px;vertical-align:top;">${escapeHtml(integration.name)}</td><td style="padding:0 0 12px;color:#9aa1b0;font-size:14px;line-height:20px;vertical-align:top;">${escapeHtml(integration.role)}</td></tr>`
    )
    .join("");

  return `<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(blueprint.name)}</title></head>
<body style="margin:0;padding:0;background:#080a0f;color:#e9eaee;font-family:Arial,Helvetica,sans-serif;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#080a0f;"><tr><td align="center" style="padding:24px 12px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:640px;background:#0c0f16;border:1px solid #232836;border-radius:18px;overflow:hidden;">
      <tr><td style="padding:28px 28px 18px;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
          <td style="color:#ea4b71;font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;font-size:11px;letter-spacing:1.5px;text-transform:uppercase;">${escapeHtml(options.brandName)}</td>
          <td align="right" style="color:#9aa1b0;font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;font-size:11px;letter-spacing:1.5px;text-transform:uppercase;">Blueprint ready</td>
        </tr></table>
        <h1 style="margin:24px 0 0;color:#ffffff;font-size:30px;line-height:36px;letter-spacing:-0.7px;">${escapeHtml(heading)}</h1>
        <p style="margin:10px 0 0;color:#b9bec9;font-size:15px;line-height:23px;">${escapeHtml(intro)}</p>
      </td></tr>
      <tr><td style="padding:12px 28px 0;">${sectionLabel("the problem")}<p style="margin:0;color:#e9eaee;font-size:15px;line-height:23px;">${escapeHtml(blueprint.problem)}</p></td></tr>
      <tr><td style="padding:28px 28px 0;">${sectionLabel("how it runs")}<table role="presentation" width="100%" cellpadding="0" cellspacing="0">${workflowRows}</table></td></tr>
      <tr><td style="padding:28px 28px 0;">${sectionLabel("workflow step · AI reasoning · human approval")}</td></tr>
      <tr><td style="padding:22px 28px 0;">${sectionLabel("inputs it needs")}<div>${inputs}</div></td></tr>
      <tr><td style="padding:20px 28px 0;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #2b3040;border-radius:14px;background:#121724;"><tr><td style="padding:20px;">
          ${sectionLabel("estimated impact")}
          <p style="margin:0;color:#ffffff;font-size:22px;font-weight:700;line-height:29px;">${escapeHtml(estimatedImpact)}</p>
          <p style="margin:2px 0 0;color:#9aa1b0;font-size:13px;line-height:19px;">${escapeHtml(estimatedImpactNote)}</p>
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:18px;"><tr><td style="width:50%;vertical-align:top;">${sectionLabel("complexity")}<p style="margin:-6px 0 0;color:#e9eaee;font-size:14px;font-weight:700;">${COMPLEXITY_LABEL[blueprint.complexity]}</p></td><td style="width:50%;vertical-align:top;">${sectionLabel("difficulty")}<p style="margin:-6px 0 0;color:#e9eaee;font-size:14px;font-weight:700;">${DIFFICULTY_LABEL[blueprint.difficulty]}</p></td></tr></table>
          <div style="margin-top:18px;padding-top:16px;border-top:1px solid #2b3040;">${sectionLabel("recommended stack")}<p style="margin:-6px 0 0;color:#e9eaee;font-size:14px;font-weight:700;line-height:21px;">${blueprint.integrations.map((integration) => escapeHtml(integration.name)).join(" &middot; ")}</p></div>
        </td></tr></table>
      </td></tr>
      <tr><td style="padding:28px 28px 0;">${sectionLabel("what each tool does")}<table role="presentation" width="100%" cellpadding="0" cellspacing="0">${integrations}</table></td></tr>
      <tr><td style="padding:16px 28px 0;">${sectionLabel("assumptions")}<table role="presentation" width="100%" cellpadding="0" cellspacing="0">${bulletList(blueprint.assumptions, "None recorded")}</table></td></tr>
      <tr><td style="padding:24px 28px 0;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #2b3040;border-radius:14px;background:#121724;"><tr><td style="padding:20px;">
          <p style="margin:0;color:#ffffff;font-size:15px;font-weight:700;line-height:22px;">Your n8n starter is attached.</p>
          <p style="margin:6px 0 0;color:#9aa1b0;font-size:14px;line-height:21px;">Import <strong style="color:#e9eaee;">${escapeHtml(options.workflowFilename)}</strong> into n8n, add your own credentials, review every field marked SETUP, test it, and activate it only when you are ready.</p>
        </td></tr></table>
      </td></tr>
      <tr><td style="padding:22px 28px 30px;color:#6f7787;font-size:11px;line-height:18px;">Requested ${escapeHtml(capturedLabel)} UTC<br>Designed by an n8n AI Agent. Figures are estimates, not measurements.</td></tr>
    </table>
  </td></tr></table>
</body>
</html>`;
}

const config = $('Configuration').first().json;
const ownerEmail = String(config.ownerEmail || '').trim().toLowerCase();
if (!/^[^s@]+@[^s@]+.[^s@]+$/.test(ownerEmail) || ownerEmail === 'you@example.com') {
  throw new Error('Set ownerEmail in the Configuration node before delivering blueprints.');
}

// Neutralize spreadsheet formula prefixes (defence in depth; the Sheets node
// also writes RAW values) so visitor text can never run as a formula.
function cellSafe(value) {
  const text = value === null || value === undefined ? '' : String(value);
  return /^[=+\-@\t\r]/.test(text) ? "'" + text : text;
}

const item = $input.first().json;
const capturedAt = item.capturedAt || new Date().toISOString();
const html = blueprintToEmailHtml(item.blueprint, {
  action: 'send-blueprint',
  firstName: item.contact.firstName,
  email: item.contact.email,
  workflowFilename: item.workflowFilename,
  capturedAt: capturedAt,
  brandName: String(config.brandName || 'Automation Blueprint'),
});

return [{
  json: Object.assign({}, item, {
    capturedAt: capturedAt,
    html: html,
    recipient: item.contact.email,
    ownerEmail: ownerEmail,
    senderName: String(config.senderName || 'Automation Blueprints'),
    // Fixed subject: no AI- or visitor-controlled text in the subject line.
    subject: 'Your automation blueprint and n8n workflow are ready',
    leadRow: {
      'Date': capturedAt,
      'First Name': cellSafe(item.contact.firstName),
      'Email': cellSafe(item.contact.email),
      'Automation': cellSafe(item.blueprint.name),
      'Problem': cellSafe(item.blueprint.problem),
      'Hours Saved per Week': item.blueprint.estimatedHoursSavedPerWeek === null ? 'Unknown' : String(item.blueprint.estimatedHoursSavedPerWeek),
      'Complexity': cellSafe(item.blueprint.complexity),
      'Session ID': cellSafe($('When chat message received').first().json.sessionId),
    },
  }),
}];
